package q.qedet.warehouse.repository; import jakarta.persistence.LockModeType; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Lock; import q.qedet.warehouse.entity.ReceivingOperation; import java.util.*;
